    expect(formatDate(date)).toBe('2023-12-25');
  });

  it('should handle single digit months with leading zero', () => {
    const date = new Date('2023-01-15T00:00:00.000Z');
    expect(formatDate(date)).toBe('2023-01-15');
  });

  it('should handle single digit days with leading zero', () => {
    const date = new Date('2023-12-05T00:00:00.000Z');
    expect(formatDate(date)).toBe('2023-12-05');
  });

  it('should handle leap year dates', () => {
    const date = new Date('2024-02-29T00:00:00.000Z');
    expect(formatDate(date)).toBe('2024-02-29');
  });

  it('should handle minimum valid date', () => {
    const date = new Date('0001-01-01T00:00:00.000Z');
    expect(formatDate(date)).toBe('0001-01-01');
  });

  it('should handle maximum reasonable date', () => {
    const date = new Date('9999-12-31T00:00:00.000Z');
    expect(formatDate(date)).toBe('9999-12-31');
  });

  it('should handle dates with time components', () => {
    const date = new Date('2023-06-15T14:30:45.123Z');
    expect(formatDate(date)).toBe('2023-06-15');
  });

  it('should handle dates in different timezones', () => {
    const date = new Date('2023-06-15T23:59:59.999-05:00');
    expect(formatDate(date)).toBe('2023-06-16');
  });

  it('should throw error for null input', () => {
    expect(() => formatDate(null as any)).toThrow('Invalid date');
  });

  it('should throw error for undefined input', () => {
    expect(() => formatDate(undefined as any)).toThrow('Invalid date');
  });

  it('should throw error for invalid date object', () => {
    const invalidDate = new Date('invalid');
    expect(() => formatDate(invalidDate)).toThrow('Invalid date');
  });

  it('should throw error for non-date object input', () => {
    expect(() => formatDate('2023-12-25' as any)).toThrow('Invalid date');
  });

  it('should throw error for number input', () => {
    expect(() => formatDate(1234567890 as any)).toThrow('Invalid date');
  });

  it('should handle date at epoch', () => {
    const date = new Date(0);
    expect(formatDate(date)).toBe('1970-01-01');
  });

  it('should handle negative timestamp dates', () => {
    const date = new Date(-86400000);
    expect(formatDate(date)).toBe('1969-12-31');
  });
});

